-- =====================================================================
--  TerraFront — Commune du jour, 2/2 : les silhouettes (a/c)
--
--  716 communes de 5 000 habitants et plus. Chaque silhouette est le
--  contour de la commune ramené dans un carré de 0 à 100 : la forme seule,
--  sans aucune coordonnée, donc rien qui permette de la retrouver sur une
--  carte. Contours : Admin Express (IGN), licence ouverte, via le dépôt
--  france-geojson, simplifiés.
--
--  À lancer APRÈS le fichier 1/2. Les trois fichiers a, b, c sont
--  indépendants, dans n'importe quel ordre. Rejouables.
-- =====================================================================

on conflict (code) do update set points = excluded.points;
